for row in pre['representatives']:
    expected=sha(OUT/row['file']);assert row['html_sha256']==expected
    assert next(r for r in cli['scenes'] if r['scene']==row['id'])['html_sha256']==expected
    br=next(r for r in bbox['scenes'] if r['scene']==row['id']);assert br['html_sha256']==expected
