    current=OUT/'preview-v2'/f'{name}.png'
    for x,p in [(0,prior),(640,current)]:
        with Image.open(p) as im:sheet.paste(im.convert('RGB').resize((640,360)),(x,i*390))
    draw.text((8,i*390+362),'V3 baseline: '+reference,font=font,fill='#173348');draw.text((648,i*390+362),'NEW PROVISIONAL: '+name,font=font,fill='#173348')
    comparisons.append({'new_preview':current.relative_to(EP).as_posix(),'new_sha256':sha(current),'prior_frame':prior.relative_to(ROOT).as_posix(),'prior_frame_sha256':sha(prior),'purpose':'style/layout hierarchy only; old numerical content is not inherited'})
